//! One test per `tests/fixtures/services/*.json` fixture (generated by build.rs): every case is run and what mercurio did is compared with `tests/snapshots/services/<fixture>.snap`. After an intended change, review and accept the new output with `cargo insta review`.
#![allow(non_snake_case, reason = "`<id>__<topic>.json` fixtures produce `<id>__<topic>` test names")]

use mercurio::testing::fixtures::{Front, record_fixture, record_fixture_with};

fn snapshot(name: &str, path: &str) {
    let blocking = record_fixture(path);
    assert_eq!(
        record_fixture_with(path, Front::Async),
        blocking,
        "{name}: AsyncMercurio differs from the blocking API"
    );
    let mut settings = insta::Settings::clone_current();
    settings.set_snapshot_path(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/snapshots/services"));
    settings.set_prepend_module_to_snapshot(false);
    settings.set_omit_expression(true);
    settings.bind(|| insta::assert_yaml_snapshot!(name, blocking));
}

include!(concat!(env!("OUT_DIR"), "/fixtures_generated.rs"));
